  assert.equal(headers["X-RateLimit-Limit"], "100");
  assert.equal(headers["X-RateLimit-Remaining"], "50");
  assert.equal(headers["X-RateLimit-Reset"], String(Math.floor(now.getTime() / 1000) + 60));
  assert.equal(headers["Retry-After"], "60");
});

